JOIN "Media" m ON m."id" = x.m
WHERE pm."productId" = p."id"
  AND pm."role" = 'PRODUCT'
  AND pm."position" = 0
  AND pm."mediaId" <> m."id"
  AND NOT EXISTS (SELECT 1 FROM "ProductMedia" d WHERE d."productId" = p."id" AND d."mediaId" = m."id" AND d."role" = 'PRODUCT');

